def decode_morse_code(morse_code):
    TOME = {
        '.-': 'a', '-...': 'b', '-.-.': 'c', '-..': 'd', '.': 'e', '..-.': 'f', '--.': 'g',
        '....': 'h', '..': 'i', '.---': 'j', '-.-': 'k', '.-..': 'l', '--': 'm', '-.': 'n',
        '---': 'o', '.--.': 'p', '--.-': 'q', '.-.': 'r', '...': 's', '-': 't', '..-': 'u',
        '...-': 'v', '.--': 'w', '-..-': 'x', '-.--': 'y', '--..': 'z', '.----': '1', '..---': '2',
        '...--': '3', '....-': '4', '.....': '5', '-....': '6', '--...': '7', '---..': '8',
        '----.': '9', '-----': '0'
    }

    def morse_to_letter(morse):
        return TOME.get(morse, ' ')

    def morse_to_word(morse_word):
        return ''.join(morse_to_letter(morse) for morse in morse_word.split())

    def morse_to_sentence(morse_sentence):
        return ' '.join(morse_to_word(morse_word) for morse_word in morse_sentence.split('  '))

    return morse_to_sentence(morse_code)

# Entry point function
def decode(s):
    return decode_morse_code(s)
```

