    return 8 <= len(s) <= 20

def contains_uppercase(s):
    return re.search(r'[A-Z]', s) is not None

def contains_lowercase(s):
    return re.search(r'[a-z]', s) is not None

def contains_digits(s):
    return re.search(r'\d', s) is not None

def contains_special_chars(s):
    return re.search(r'[!@#$%^&*?]', s) is not None

def check_password(s):
    return "valid" if (is_valid_length(s) and 
                      contains_uppercase(s) and 
                      contains_lowercase(s) and 
                      contains_digits(s) and 
                      contains_special_chars(s)) else "not valid"
```

